return {yjhnpc01={id="yjhnpc01",baseId="rwnpc01",combatid={1,1001},name="红娘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37002",2}},{type="doc",args={"YEL红娘：久闻少侠大名！恰逢七夕之际，我是被红娘堂派来此地撮合姻缘的红娘。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL红娘：方才叶惊鸿，叶捕头前来邀我同去东北面的大街口，好挑件合适的礼物送给他的心上人。唔......可惜我对这小镇还不太熟悉，不知少侠能否替我跑一趟？"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="redoc",args={"YEL红娘：少侠放心，我红娘堂的人不会让你白跑，自会有好礼相酬。NOR","YEL红娘：叶捕头现在就在东北面的大街口等着，少侠若能成就一段良缘那便再好不过。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="gaintab",args={"37001",2}},{type="gaintab",args={"37002",7}},{type="doc",args={"CYN你将方才发生的事情告知了红娘。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL红娘：虽说有些不顺利，但看这二人红鸾星动，只怕好事将近，想来，少侠也不必忧心。今日辛苦少侠，这是你我说好的谢礼。NOR"}},{type="delayer",args={0.7,"少侠，稍安勿躁！"}},{type="showbutton",args={3,0}},{type="showbutton",args={4,1}},{type="outgame",args={"hdrole0805"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="redoc",args={"YEL红娘：惊鸿燕、叶惊鸿，这二人的名字倒是有意思，少侠说是不是？NOR","YEL红娘：我听说这惊鸿燕乃是出自盗墓世家，一个兵一个贼，有意思。NOR","YEL红娘：红娘堂打探消息的本事虽不如那天机老人，但若论及“姻缘”二字，江湖中怕是无人敢称第一。NOR","YEL红娘：我这里的八卦可都和江湖上的侠侣有关，少侠得空时，我们可以一起探讨探讨。NOR"}}},caozuoName5="交谈",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="gaintab",args={"37001",2}},{type="gaintab",args={"37002",7}},{type="doc",args={"CYN你将方才发生的事情告知了红娘。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL红娘：好极好极，哈哈哈，想不到少侠能如此成功地撮合这二人，红娘在此谢过，小小心意，望少侠笑纳！NOR"}},{type="delayer",args={0.7,"少侠，稍安勿躁！"}},{type="showbutton",args={5,0}},{type="showbutton",args={4,1}},{type="outgame",args={"hdrole0805"}}},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"37002",6}},{type="equaltab",args={"37009",1}}}},autoResult1={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"37002",6}},{type="equaltab",args={"37010",1}}}},autoResult2={{type="showbutton",args={2,0}},{type="showbutton",args={5,1}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},yjhnpc02={id="yjhnpc02",baseId="rwnpc02",combatid={1,1001},name="叶惊鸿",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37002",3}},{type="doc",args={"YEL叶惊鸿：恰逢佳节，我想寻件珍品送予小燕，但看这古董货架上琳琅满目，却不知道选什么才好。不知少侠可懂古玩？NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL叶惊鸿：少侠若能从古董货架上帮我挑选出珍品，那就再好不过。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="gaintab",args={"37002",5}},{type="doc",args={"YEL叶惊鸿：少侠挑选的必然不会错，我这就去找小燕！NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="outobject",args={"yjhnpc02"}},{type="doc",args={"CYN叶惊鸿欣喜的买下你所挑选的珍品，朝着镇外的碎石小路走去。不知惊鸿燕是否会喜欢这件礼物，不妨先跟上去看看。NOR"}}},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"37002",4}}}},autoResult1={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},yjhnpc02a={id="yjhnpc02a",baseId="rwnpc02",combatid={1,1001},name="叶惊鸿",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37002",6}},{type="doc",args={"YEL叶惊鸿：这事不怨你。不过，看来待会儿我还得再回去给小燕挑件礼物。今日辛苦少侠了，烦劳代我也向红娘致谢。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL叶惊鸿：我看那古董商老实，谁知......待七夕结束，我定要带他去衙门里喝喝茶水，也替我挑挑衙门里的珍宝。NOR"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},yjhnpc02b={id="yjhnpc02b",baseId="rwnpc02",combatid={1,1001},name="叶惊鸿",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37002",6}},{type="doc",args={"YEL叶惊鸿：小燕很喜欢这件礼物，叶某在此谢过少侠，还请少侠也替我告知红娘，我与小燕一切安好。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL叶惊鸿：小燕只要喜欢，那便都好。NOR"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},yjhnpc03={id="yjhnpc03",baseId="rwnpc03",combatid={1,1001},name="古董商",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL古董商：东西都在这儿，少侠看上什么了只管同我说就是。不过......咱话可得说在前头，古玩这行，就看个儿眼劲儿，若少侠看走了眼——货物离柜概不负责。你可不能把火撒在我头上。NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL古董商：少侠好眼光。NOR"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"37002",4}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"37002",6}}}},autoResult2={{type="change",args={"yjhnpc03","bsnpc02"}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},yjhnpc04={id="yjhnpc04",baseId="rwnpc04",combatid={1,1001},name="惊鸿燕",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL惊鸿燕：这姓叶的愈发嚣张了，我可不能再让他这么得意。NOR"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},yjhnpc04a={id="yjhnpc04a",baseId="rwnpc04",combatid={1,1001},name="惊鸿燕",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL惊鸿燕：与天毋极，与地相长。怡乐未央，长毋相忘。咳咳，这姓叶的什么时候变得这么通透了，老实交代，是不是少侠教他的？NOR"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},ddxnpc01={id="ddxnpc01",baseId="rwnpc01",combatid={1,1001},name="红娘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37003",2}},{type="doc",args={"YEL红娘：久闻少侠大名！恰逢七夕之际，我是被红娘堂派来此地撮合姻缘的红娘。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL红娘：方才红娘堂的人跑来同我说，有个姓丁的傻小子在北内大街丢了魂儿，保不定是看上了哪家的红粉俏佳人，少侠不妨替我跑跑腿牵了这根红线？NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="redoc",args={"YEL红娘：老规矩，好处少不了你的。NOR","YEL红娘：那傻小子就在北内大街，少侠可别忘了。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="gaintab",args={"37001",2}},{type="gaintab",args={"37003",13}},{type="doc",args={"YEL红娘：噗嗤，没想到那姓丁的看着是个豪杰样，遇了这儿女情长之事倒真成了呆子。此番辛苦少侠了，这是你我说好的谢礼。NOR"}},{type="delayer",args={0.7,"少侠，稍安勿躁！"}},{type="showbutton",args={3,0}},{type="showbutton",args={4,1}},{type="outgame",args={"hdrole0805"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="redoc",args={"YEL红娘：宁可枝头抱香死，何曾吹落北风中。至少此刻，这姻缘是成了，又何必忧心他朝，少侠说是与不是？NOR","YEL红娘：我这可有桩八卦，且说这凌小姐的父亲前些时候从天竺寻了个奇珍，叫什么“波旬”......不知是用来作何用处。NOR","YEL红娘：前几日，我听说江湖中有伙人准备报团殴打凌知府。唔，其实我也想给他画个圈圈，可惜啊，恶人遗千年，所以......我把他在姻缘簿上的名字都勾了，让他注！孤！生！NOR"}}},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"37003",13}}}},autoResult1={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},ddxnpc02={id="ddxnpc02",baseId="rwnpc05",combatid={1,1001},name="丁大侠",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37003",3}},{type="doc",args={"YEL丁大侠：丁某从未听说过这“绿水秋波”，看了半天，实在认不出。不知少侠可懂菊？若能从卖花郎处帮丁某认出这盆“绿水秋波”，丁某定不忘大恩。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL丁大侠：前些时候在一场菊花会上，丁某遇到了此生心仪之人，并以那“绿菊”结缘。方才她就站在这里，丁某远远地看着......想她应是喜欢这盆“绿水秋波”的。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL丁大侠：认不出也不妨事，少侠莫要介怀。看来，丁某是无缘得到这盆“绿水秋波”送予她了。NOR"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="gaintab",args={"37003",7}},{type="doc",args={"YEL丁大侠：有劳少侠！丁某感激不尽。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"CYN丁大侠走上前，将银子交给了卖花郎，买下了那盆“绿水秋波”，奇怪的是，他得到这盆菊花后不喜反愁。NOR"}},{type="showbutton",args={4,0}},{type="showbutton",args={5,1}},{type="refresh",args={}}},caozuoName5="交谈",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="gaintab",args={"37003",8}},{type="doc",args={"YEL丁大侠：我若直接拿着这盆“绿水秋波”去找她，只怕唐突。能否请少侠为媒，前去东内大街将这盆菊送予她，并替丁某引见？NOR"}},{type="itemin",args={"23qxrwwp01",1}},{type="tips",args={"获得绿水秋波菊*1"}},{type="showbutton",args={5,0}},{type="showbutton",args={6,1}},{type="refresh",args={}}},caozuoName6="交谈",buttonShow6=0,condition6={relation="and",conditions={{type="kick",args={}}}},result6={{type="doc",args={"YEL丁大侠：丁某久在江湖，自然不应拘泥小节，但她乃是翰林之女，不比江湖儿女。丁某希望在她眼中，我并非是个唐突无礼的江湖浪客。NOR"}}},autoCondition1={relation="and",conditions={{type="equaltab",args={"37003",5}}}},autoResult1={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"37003",6}}}},autoResult2={{type="showbutton",args={2,0}},{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},autoCondition3={relation="and",conditions={{type="equaltab",args={"37003",9}}}},autoResult3={{type="change",args={"ddxnpc02","ddxnpc02a"}}},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},ddxnpc02a={id="ddxnpc02a",baseId="rwnpc05",combatid={1,1001},name="丁大侠",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37003",10}},{type="doc",args={"YEL丁大侠：凌小姐当真愿意见丁某！丁某、丁某多谢少侠大恩，我这便前去流樱湖等她。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="outobject",args={"ddxnpc02a"}},{type="doc",args={"CYN丁大侠喜不自胜，步伐轻盈的朝着流樱湖而去。不知两人会有何发展，不妨先跟上去看看。NOR"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},ddxnpc02b={id="ddxnpc02b",baseId="rwnpc05",combatid={1,1001},name="丁大侠",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37003",13}},{type="doc",args={"YEL丁大侠：多谢少侠为媒，让我能和凌妹再见一面，此恩此情，丁某永生不忘！NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL丁大侠：能与凌妹见上一面，丁某便似做了神仙，不、神仙也必定没我这般快活。NOR"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},ddxnpc03={id="ddxnpc03",baseId="rwnpc06",combatid={1,1001},name="卖花郞",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL卖花郎：这些菊花可都是我精心培育的，耗费了不少心力。NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="gaintab",args={"37003",4}},{type="doc",args={"YEL卖花郎：素来懂菊者甚少，我也不会欺负外行人。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL卖花郎：少侠可听好，我在这四盆菊花盆上都贴了红纸，红纸上写着诸多“直”字。少侠若能从其中一张红纸上找到一个“真”字，那这盆菊便是真正的“绿水秋波”。NOR"}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}},{type="refresh",args={}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL卖花郎：少侠可记住了，只有“绿水秋波”花盆上的红纸中藏着一个“真”字，待你选好后，我自会分辨真伪。NOR"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL卖花郎：少侠是否还想再试一次？NOR"}}},caozuoName5="交谈",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="doc",args={"YEL卖花郎：少侠好眼光，竟找出了这盆真的“绿水秋波”。NOR"}}},caozuoName6="交谈",buttonShow6=0,condition6={relation="and",conditions={{type="kick",args={}}}},result6={{type="doc",args={"YEL卖花郎：我这菊不少富贵人家都求着来买，少侠与这位公子当真都是好眼光。NOR"}}},autoCondition1={relation="and",conditions={{type="equaltab",args={"37003",3}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"37003",5}}}},autoResult2={{type="showbutton",args={3,0}},{type="showbutton",args={4,1}}},autoCondition3={relation="and",conditions={{type="equaltab",args={"37003",6}}}},autoResult3={{type="showbutton",args={3,0}},{type="showbutton",args={4,0}},{type="showbutton",args={5,1}}},autoCondition4={relation="and",conditions={{type="equaltab",args={"37003",8}}}},autoResult4={{type="showbutton",args={5,0}},{type="showbutton",args={6,1}}},autoCondition5={relation="and",conditions={{type="equaltab",args={"37003",9}}}},autoResult5={{type="outobject",args={"ddxnpc03"}}},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},ddxnpc04={id="ddxnpc04",baseId="rwnpc07",combatid={1,1001},name="凌小姐",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL凌小姐：方才我似在人群外看见了他，却也只是匆匆一瞥，再不敢多看一眼。NOR"}}},caozuoName2="送礼",buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="gaintab",args={"37003",9}},{type="tips",args={"失去绿水秋波菊*1"}},{type="itemout",args={"23qxrwwp01",1}},{type="doc",args={"CYN你将丁大侠买的绿水秋波菊送给了凌小姐，丫环上前接过，却“咦”了一声。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL凌府丫环：这姓丁的还真是憨傻，被人骗了还懵懂不知，这哪里是“绿水秋波”，分明是盆普通的白菊着了颜色。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL凌小姐：呵，他哪里憨傻......他只是知我喜欢。烦请少侠转告，这盆“绿水秋波”我很喜欢，稍后我会在流樱湖等他。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}},{type="refresh",args={}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL凌小姐：我知道这菊是假，却不想仅这一瞥他就上了心，如此，我便欢喜。NOR"}}},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="tabgr",args={"37003",9}}}},autoResult1={{type="outobject",args={"ddxnpc04"}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},ddxnpc04a={id="ddxnpc04a",baseId="rwnpc07",combatid={1,1001},name="凌小姐",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL凌小姐：我瞧着他倒消瘦了几分，不知可是病了。NOR"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},ddxnpc05={id="ddxnpc05",baseId="rwnpc08",combatid={1,1001},name="凌府丫环",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL凌府丫环：小姐吩咐我在此等她。NOR"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},qbynpc01={id="qbynpc01",baseId="rwnpc01",combatid={1,1001},name="红娘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37004",2}},{type="doc",args={"YEL红娘：我做了数载红娘，最是见不得别人为情所困，刚经过湖畔瞧见一位求而不得的痴情人，若少侠能替我助他一把，红娘必有重谢。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="redoc",args={"YEL红娘：老规矩，好处少不了你的。NOR","YEL红娘：那痴情人就在湖畔，少侠可别忘了。NOR","YEL红娘：对我而言人生最快乐的事，当然是让姻缘簿上未婚的侠客牵线成功。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="gaintab",args={"37001",2}},{type="gaintab",args={"37004",8}},{type="doc",args={"YEL红娘：山月不知心里事，水风空落眼前花，有了今日这出，这明月便不会那么遥不可及了吧，我已为少侠备好薄礼，还请少侠收下。NOR"}},{type="delayer",args={0.7,"少侠，稍安勿躁！"}},{type="showbutton",args={3,0}},{type="showbutton",args={4,1}},{type="outgame",args={"hdrole0805"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="redoc",args={"YEL红娘：我偷偷和你说哦，齐伯庸这人看似潇洒不羁，结果倾心他师姐多年，一直没胆量表明心迹。NOR","YEL红娘：洛还君的身世我也知道，毕竟她老爹老母的姻缘可在我这簿子上！唔，这可是能引起江湖……打住，嘘，我不能说。NOR"}}},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"37004",7}}}},autoResult1={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},qbynpc02={id="qbynpc02",baseId="rwnpc09",combatid={1,1001},name="齐伯庸",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL齐伯庸：你也来这赏景？可惜没有烟花应衬，称不上意境绝佳。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="gaintab",args={"37004",3}},{type="doc",args={"YEL齐伯庸：既然少侠一再对齐某表示关怀之意，齐某便如实说了罢，我在此处等人，原想买烟花应景，但又担心我此时离开会和她错过，少侠若能替齐某将烟花买来，齐某将不胜感激。NOR"}},{type="itemin",args={"23qxrwwp08",1}},{type="tips",args={"获得钱袋*1"}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="redoc",args={"YEL齐伯庸：我担心此时离开会和她错过，少侠若能替齐某将烟花买来，齐某将不胜感激。NOR","YEL齐伯庸：那卖烟花的商贩应当就在北大街附近，拜托少侠了。NOR"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="doc",args={"YEL齐伯庸：少侠可有买到烟花？NOR"}}},caozuoName5="给予烟花",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="gaintab",args={"37004",5}},{type="doc",args={"CYN你将烟花送予齐伯庸。NOR"}},{type="itemout",args={"23qxrwwp02",1}},{type="tips",args={"失去烟花*1"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL齐伯庸：齐某谢过少侠，只是眼看约定的时辰已过，我所约之人仍然未至，齐某不免有些担忧，能否再请少侠前往小镇西门，若找到洛还君，还请带话，便说我会在此一直等她。NOR"}},{type="showbutton",args={4,0}},{type="showbutton",args={5,0}},{type="showbutton",args={6,1}}},caozuoName6="交谈",buttonShow6=0,condition6={relation="and",conditions={{type="kick",args={}}}},result6={{type="redoc",args={"YEL齐伯庸：月是水中月，人是天上人。NOR","YEL齐伯庸：我这份情意只敢显露一角，大部分时候默默隐藏心底罢了。NOR","YEL齐伯庸：还请少侠前往小镇西门帮我替洛还君带句话，便说我会在此一直等她。NOR"}}},autoCondition1={relation="and",conditions={{type="equaltab",args={"37004",4}}}},autoResult1={{type="showbutton",args={3,0}},{type="showbutton",args={4,1}},{type="showbutton",args={5,1}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"37004",6}}}},autoResult2={{type="gaintab",args={"37004",7}},{type="change",args={"qbynpc02","qbynpc02a"}},{type="addobject",args={"qbynpc03"}},{type="doc",args={"CYN湖畔边他们二人并肩而立，宛如一对璧人，烟花的在夜空中不断绽放，仿若看见漫天星雨。NOR"}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},qbynpc02a={id="qbynpc02a",baseId="rwnpc09",combatid={1,1001},name="齐伯庸",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"CYN你见两人正共赏空中美景相谈甚欢，便打消了上前搭话的念头。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"CYN还是回中央广场回复红娘吧。NOR"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},qbynpc03={id="qbynpc03",baseId="rwnpc11",combatid={1,1001},name="洛还君",teamMark=-1,