intab",args={"37005",7}},{type="doc",args={"YEL红娘：信送到就好，这姻缘呐天定，谁又说得准呢？NOR"}},{type="showbutton",args={3,0}},{type="showbutton",args={4,1}},{type="outgame",args={"hdrole0805"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="redoc",args={"YEL红娘：瞧着这紫姑娘也不错，就是阴毒了些，稍后呀我送些防身的药草给萧大侠，否则怕他吃不消。NOR","YEL红娘：实不相瞒，我前日从市集上寻了本小册，叫《我与姊夫二八事》，少侠可感兴趣？一起啊！NOR"}}},caozuoName5="交谈",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="gaintab",args={"37001",2}},{type="gaintab",args={"37005",6}},{type="doc",args={"YEL红娘：这么说，少侠阴差阳错还解了一局死棋，促了段美好姻缘，哈哈哈，好极好极！NOR"}},{type="showbutton",args={5,0}},{type="showbutton",args={6,1}},{type="outgame",args={"hdrole0805"}}},caozuoName6="交谈",buttonShow6=0,condition6={relation="and",conditions={{type="kick",args={}}}},result6={{type="redoc",args={"YEL红娘：看来我得改改江湖的小道消息，谁叫我是萧朱党呢！NOR","YEL红娘：少侠对撮合姻缘一事倒很有天赋，不知以后是否得空来我红娘堂当个“红娘”？NOR"}}},autoCondition1={relation="and",conditions={{type="equaltab",args={"37005",6}},{type="equaltab",args={"37011",1}}}},autoResult1={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"37005",6}},{type="equaltab",args={"37012",1}}}},autoResult2={{type="showbutton",args={2,0}},{type="showbutton",args={5,1}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},xdxnpc02={id="xdxnpc02",baseId="rwnpc12",combatid={1,100016},name="朱姑娘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL朱姑娘：萧大哥有封信被巡城马错送到了红娘那里，我寻到红娘处，这才追赶而来。还请少侠将信直接交给我吧，也省了麻烦。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="showbutton",args={3,1}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL朱姑娘：辛苦少侠了，这封信我会亲自送给段王爷。NOR"}}},caozuoName3="归还",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="choice",args={"是否归还信件？",{"是",{{"gaintab",{"37005",4}},{"gaintab",{"37011",1}},{"doc",{[[CYN你将信件递还给朱姑娘，她欣然一笑，反倒出奇的朝着镇外的平丘山走去。NOR
