。NOR"}}},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},xdxnpc03a={id="xdxnpc03a",baseId="rwnpc13",combatid={1,1001},name="萧大侠",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37005",6}},{type="doc",args={"YEL萧大侠：信的事情，朱妹已经告诉我了，她当真傻......竟拦下了那封信，又提前告知段王爷我不会赴约......NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL萧大侠：对了，有关巡城马送错信的事情还请少侠替我谢谢红娘。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL萧大侠：我知她......以后会替她好好照顾紫姑娘。NOR"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},xdxnpc04={id="xdxnpc04",baseId="rwnpc14",combatid={1,1001},name="紫姑娘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL紫姑娘：姊姊、姊姊，我倒该谢你，还是该怨你？NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="redoc",args={"YEL紫姑娘：你可别欺负我，我姊夫可是了不得的大侠！NOR","YEL紫姑娘：我不管，这辈子我跟定我姊夫了。NOR"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"37005",6}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},dxnpc01={id="dxnpc01",baseId="rwnpc01",combatid={1,1001},name="红娘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37006",2}},{type="doc",args={"YEL红娘：方才有位公子惹了他娘子不开心，我瞧着那小娘子也并非真的生气，若能撮合二人，令他们和好如初再好不过。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL红娘：那公子现在在西北面的大街口急的满头大汗，少侠可到那处去寻他。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="redoc",args={"YEL红娘：老规矩，好处少不了你的。NOR","YEL红娘：那公子现在在西北面的大街口急的满头大汗，少侠可到那处去寻他。NOR","YEL红娘：夫妻嘛，床头打架床尾和，再寻常不过，但若是一不小心，飞鸟各投林，那就惨了。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="gaintab",args={"37001",2}},{type="gaintab",args={"37006",7}},{type="doc",args={"YEL红娘：少侠今可有三喜，一喜促良缘，二喜逢故人，至于这三喜嘛......自然是我这红娘赠予少侠的谢礼！NOR"}},{type="delayer",args={0.7,"少侠，稍安勿躁！"}},{type="showbutton",args={3,0}},{type="showbutton",args={4,1}},{type="outgame",args={"hdrole0805"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="redoc",args={"YEL红娘：江湖之大，能得一知己相伴，夫复何求。不过说到这姻缘，少侠猜猜自己的姻缘可在我这姻缘簿上？NOR","YEL红娘：我前日听隔壁的王婆说，撞见了那袁半飞在帮官府办事。我与她做赌，赌这袁半飞可还有撬墙角的机会，身为红娘，这实在不该、不该。NOR","YEL红娘：我前日逛集市，又得了本好册子，叫《任天南与段天溟二三事》，少侠可要一起观摩观摩？NOR"}}},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"37006",6}}}},autoResult1={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},dxnpc02={id="dxnpc02",baseId="rwnpc15",combatid={1,100015},name="小贼",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL小贼：小爷我也是练家子，再拦我，可别说我欺负你。NOR"}}},caozuoName2="擒住",buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="challenge",args={"dxnpc02"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="challengewin",args={"dxnpc02"}}}},autoResult1={{type="gaintab",args={"37006",4}},{type="doc",args={[[CYN小贼被你打的连声求饶，又担心你报官，索性将钱袋朝你一扔，当即脚底抹油溜走了。NOR
CYN你正要寻找失主，却见一位故人右手抱着一堆布匹，左手提着包裹好的糕点，挤开人群，满头大汗的朝你走来。看来这“失主”便是这位故人了。NOR]]}},{type="itemin",args={"23qxrwwp04",1}},{type="tips",args={"获得织蓝钱袋*1"}},{type="addobject",args={"dxnpc03"}},{type="outobject",args={"dxnpc02"}}},autoCondition2={relation="and",conditions={{type="challengelose",args={"dxnpc02"}}}},autoResult2={{type="gaintab",args={"37006",4}},{type="doc",args={[[CYN小贼与你缠斗许久，担心将官府引来，索性将钱袋朝你一扔，脚底抹油溜走了。NOR
CYN你正要寻找失主，却见一位故人右手抱着一堆布匹，左手提着包裹好的糕点，挤开人群，满头大汗的朝你走来。看来这“失主”便是这位故人了。NOR]]}},{type="itemin",args={"23qxrwwp04",1}},{type="tips",args={"获得织蓝钱袋*1"}},{type="addobject",args={"dxnpc03"}},{type="outobject",args={"dxnpc02"}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},dxnpc03={id="dxnpc03",baseId="rwnpc16",combatid={1,1001},name="段潇",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL段潇：少侠！你怎会也在此？NOR"}}},caozuoName2="交还钱袋",buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="gaintab",args={"37006",5}},{type="itemout",args={"23qxrwwp04",1}},{type="tips",args={"失去织蓝钱袋*1"}},{type="doc",args={"YEL段潇：红娘说会有人来助我，故小可便在此等待，等的久了我就想着去周围的铺子里买些东西讨临烟喜欢，谁知那小贼趁我拿东西的时候顺手牵羊。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL段潇：银钱丢了也没什么，只是那钱袋可不能丢......不过，能在此遇到少侠当真好！临烟见了你气都消了。来，小可带你去见她。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"CYN段潇一边说着，一边领着你朝着浮云寺的内寺走去。NOR"}},{type="outobject",args={"dxnpc03"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},dxnpc03a={id="dxnpc03a",baseId="rwnpc16",combatid={1,1001},name="段潇",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37006",6}},{type="doc",args={"YEL沐临烟：方才段大哥说少侠来了，临烟还不相信，如今一见，当真惊喜。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL段潇：看临烟这般，方才的气定然都消了。少侠可得替小可多谢谢红娘，自然，这也是少侠的功劳！NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="redoc",args={"YEL段潇：能与少侠江湖再见，小可喜不自胜。NOR","YEL段潇：这段时日，我与临烟走南闯北，倒觉得自己前半生尽荒唐，如今想来倒像是噩梦初醒后的向死而生。NOR"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"37006",6}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},dxnpc04={id="dxnpc04",baseId="rwnpc17",combatid={1,1001},name="沐临烟",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37006",6}},{type="doc",args={"YEL沐临烟：方才段大哥说少侠来了，临烟还不相信，如今一见，当真惊喜。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL段潇：看临烟这般，方才的气定然都消了。少侠可得替小可多谢谢红娘，自然，这也是少侠的功劳！NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="redoc",args={"YEL沐临烟：我哪里是生段大哥的气，只不过想劝他放下大仇，如此逍遥一世罢了。我知他不会放弃，但若不劝，我心中实在不安......NOR","YEL沐临烟：今日得见，可要与少侠好好一聚。NOR"}}},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"37006",6}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},qynznpc01={id="qynznpc01",baseId="rwnpc01",combatid={1,1001},name="红娘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37007",2}},{type="doc",args={"YEL红娘：今日在东内大街有一位青衣男子，为给心仪女子送礼几经波折未果，红娘我既瞧见此事，岂有不管之理，少侠能否代我前去相助一番？NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="redoc",args={"YEL红娘：老规矩，好处少不了你的。NOR","YEL红娘：那青衣男子就在东内大街，少侠可别忘了。NOR","YEL红娘：人家才不是多管闲事，我的宏愿一般人可不懂。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="gaintab",args={"37001",2}},{type="gaintab",args={"37007",8}},{type="doc",args={"YEL红娘：不错，不错，让有情人心相系，我的名册上又可以为自己记下一功。红娘还有份薄礼要赠与少侠，多谢少侠跑这一趟。NOR"}},{type="delayer",args={0.7,"少侠，稍安勿躁！"}},{type="showbutton",args={3,0}},{type="showbutton",args={4,1}},{type="outgame",args={"hdrole0805"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="redoc",args={"YEL红娘：湖上每对侠侣的感情动静，可都逃不过我的眼睛。NOR","YEL红娘：作为一名优秀的红娘，当然能把所有刻意的安排变成浪漫的巧合。NOR","YEL红娘：感情的学问复杂着呢，以后等我写本专门诠释男女之情的书册，可送少侠一观。NOR"}}},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"37007",6}}}},autoResult1={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},qynznpc02={id="qynznpc02",baseId="rwnpc18",combatid={1,1001},name="摊主",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"YEL摊主：老叟做了大半辈子的面具，每张面具都独一无二，客官要不要买上一张？NOR"}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="redoc",args={"YEL摊主：少侠要是想套面具，还请不要使用武功，给老叟留口饭吃。NOR","YEL摊主：若套中的面具不是付钱时说好的那个，按规矩可不能带走。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="redoc",args={"YEL摊主：恭喜少侠，老叟制作的面具可是最受镇上小娘子的喜欢。NOR","YEL摊主：逛花灯，戴千面，约见相思人。NOR"}}},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"37007",3}}}},autoResult1={{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},autoCondition2={relation="and",conditions={{type="equaltab",args={"37007",4}}}},autoResult2={{type="showbutton",args={1,0}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},qynznpc03={id="qynznpc03",baseId="rwnpc25",combatid={1,1001},name="青衣男子",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37007",3}},{type="doc",args={"YEL青衣男子：少侠，好久不见，没想到在这遇见你。NOR"}},{type="doc",args={"YEL青衣男子：岳姑娘想要那个白狐狸面具，我已付了银钱，可惜试了几次都没能套中，能否请少侠帮忙？NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}},{type="refresh",args={}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL青衣男子：这几日我见她闷闷不乐，她既开口，无论如何我都要满足，望她能开心一些。NOR"}}},caozuoName3="给予面具",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="gaintab",args={"37007",5}},{type="doc",args={"CYN你正欲将白狐狸面具递给青衣男子，突听人群中一位书生高喊“抓小偷，我的钱袋不见了”。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL青衣男子：少侠，还得麻烦你去一趟浮云寺，代我将面具送给岳姑娘。NOR"}},{type="outobject",args={"qynznpc03"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"CYN他匆忙说完，眨眼间朝贼人逃跑的方向追去。NOR"}}},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"37007",4}}}},autoResult1={{type="showbutton",args={3,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},qynznpc03a={id="qynznpc03a",baseId="rwnpc25",combatid={1,1001},name="青衣男子",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"CYN他们二人之间似乎有种微妙的气氛升腾，你心觉此时上前打扰颇为无礼，便没有再去搭话。NOR"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},qynznpc04={id="qynznpc04",baseId="rwnpc19",combatid={1,1001},name="岳姑娘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="redoc",args={"YEL岳姑娘：好巧，你也是来解签？我在这等人，可是他还没到。NOR","CYN她朝门外探视，面露失望，手里的一根姻缘签上写着醒目的中下签。NOR"}}},caozuoName2="给予面具",buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="gaintab",args={"37007",6}},{type="itemout",args={"23qxrwwp05",1}},{type="tips",args={"失去白狐狸面具*1"}},{type="doc",args={"CYN你递给她白狐狸面具，并说出青衣男子没来的原因。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL岳姑娘：这是……我前几日来寺庙求签，听说今天会有卖狐狸面具的小摊，便随口一提，没料想他竟还记得。NOR"}},{type="doc",args={"CYN岳姑娘手指轻柔地抚摸着白狐狸面具，好似这是一件易碎的珍宝。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL岳姑娘：多谢少侠，我会继续留在这里等他。NOR"}}},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"37007",8}}}},autoResult1={{type="change",args={"qynznpc04","qynznpc04a"}},{type="addobject",args={"qynznpc03a"}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},qynznpc04a={id="qynznpc04a",baseId="rwnpc20",combatid={1,1001},name="面具姑娘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="doc",args={"CYN他们二人之间似乎有种微妙的气氛升腾，你心觉此时上前打扰颇为无礼，便没有再去搭话。NOR"}}},buttonShow2=1,condition2={relation="and",conditions={{type="kick",args={}}}},result2={},buttonShow3=1,condition3={relation="and",conditions={{type="kick",args={}}}},result3={},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={}},autoResult1={},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},zdxnpc01={id="zdxnpc01",baseId="rwnpc01",combatid={1,1001},name="红娘",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37008",2}},{type="doc",args={"YEL红娘：我仰慕的一对侠侣近日也来到这平安小镇，我瞧着他们二人之间似乎闹了点矛盾，现张大侠满脸愁思，在平安东街徘徊了一个时辰，少侠若得空，能否帮我看看什么情况，尽量助他一把。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="redoc",args={"YEL红娘：老规矩，好处少不了你的。NOR","YEL红娘：那张大侠就在平安东街，少侠可别忘了。NOR","YEL红娘：情之一字从来没有正确答案，有时候红娘我也不懂为情烦恼的人。NOR"}}},caozuoName3="交谈",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="gaintab",args={"37001",2}},{type="gaintab",args={"37008",8}},{type="doc",args={"YEL红娘：原来张大侠是为这事发愁，确实现在正是放河灯的好时候，流灯星河，一年少有的情景，少侠稍后若去湖畔，说不定能一睹殷女侠的风采呢，我这里有份小礼赠与少侠，就当做是给少侠的酬谢。NOR"}},{type="delayer",args={0.7,"少侠，稍安勿躁！"}},{type="showbutton",args={3,0}},{type="showbutton",args={4,1}},{type="outgame",args={"hdrole0805"}}},caozuoName4="交谈",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="redoc",args={"YEL红娘：生亦同生，死亦同往，世间能有几个这样的痴心人。NOR","YEL红娘：江湖中真实的爱恨情仇，可比话本里的故事有趣多了。NOR"}}},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"37008",7}}}},autoResult1={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},zdxnpc02={id="zdxnpc02",baseId="rwnpc21",combatid={1,1001},name="张大侠",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37008",3}},{type="doc",args={"YEL张大侠：为何大街口的卖灯老人今日没有售卖白兔河灯，她既点名说要这个，我若不买，她定会更加恼我，这可怎办。NOR"}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},caozuoName2="交谈",buttonShow2=0,condition2={relation="and",conditions={{type="kick",args={}}}},result2={{type="doc",args={"YEL张大侠：为何大街口的卖灯老人今日没有售卖白兔河灯，她既点名说要这个，我若不买，她定会更加恼我，这可怎办。NOR"}}},caozuoName3="给予河灯",buttonShow3=0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="gaintab",args={"37008",7}},{type="tips",args={"失去兔子河灯*1"}},{type="itemout",args={"23qxrwwp07",1}},{type="doc",args={"YEL张大侠：多谢少侠，这可真是及时雨，解了在下燃眉之急，只是在下另有要事需先行一步，少侠恩情他日若有机会必定偿还。NOR"}},{type="outobject",args={"zdxnpc02"}}},buttonShow4=1,condition4={relation="and",conditions={{type="kick",args={}}}},result4={},buttonShow5=1,condition5={relation="and",conditions={{type="kick",args={}}}},result5={},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"37008",6}}}},autoResult1={{type="showbutton",args={3,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",cond