0,condition3={relation="and",conditions={{type="kick",args={}}}},result3={{type="doc",args={"YEL卖灯老人：可有拿到浆糊？NOR"}}},caozuoName4="给予浆糊",buttonShow4=0,condition4={relation="and",conditions={{type="kick",args={}}}},result4={{type="gaintab",args={"37008",6}},{type="tips",args={"失去浆糊*1"}},{type="itemout",args={"23qxrwwp06",1}},{type="doc",args={"YEL卖灯老人：客官稍候片刻。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"CYN老人说完开始制作花灯，手指灵活翻飞，看得你眼花缭乱，不到一盏茶工夫你便听老人说道：“兔子河灯已做好。”NOR"}},{type="tips",args={"获得兔子河灯*1"}},{type="itemin",args={"23qxrwwp07",1}},{type="showbutton",args={3,0}},{type="showbutton",args={4,0}},{type="showbutton",args={5,1}}},caozuoName5="交谈",buttonShow5=0,condition5={relation="and",conditions={{type="kick",args={}}}},result5={{type="redoc",args={"YEL卖灯老人：老叟从不愿欠别人半分，区区一个河灯，客官安心收下吧。NOR","YEL卖灯老人：河灯璀璨，映照天上鹊桥，若不放一盏河灯，佳节就少了点什么。NOR"}}},buttonShow6=1,condition6={relation="and",conditions={{type="kick",args={}}}},result6={},autoCondition1={relation="and",conditions={{type="equaltab",args={"37008",5}}}},autoResult1={{type="showbutton",args={2,0}},{type="showbutton",args={3,1}},{type="showbutton",args={4,1}}},autoCondition2={relation="and",conditions={}},autoResult2={},autoCondition3={relation="and",conditions={}},autoResult3={},autoCondition4={relation="and",conditions={}},autoResult4={},autoCondition5={relation="and",conditions={}},autoResult5={},autoCondition6={relation="and",conditions={}},autoResult6={},autoCondition7={relation="and",conditions={}},autoResult7={}},zdxnpc04={id="zdxnpc04",baseId="rwnpc23",combatid={1,1001},name="王二",teamMark=-1,canSee=1,caozuoName1="交谈",buttonShow1=1,condition1={relation="and",conditions={{type="kick",args={}}}},result1={{type="gaintab",args={"37008",5}},{type="doc",args={"CYN你向他说明是受卖灯老人的吩咐来取浆糊。NOR"}},{type="delayer",args={1,"少侠，稍安勿躁！"}},{type="doc",args={"YEL王二：今天生意忙脱不开身，这才给耽误了，劳您给卖灯老人送过去。NOR"}},{type="tips",args={"获得浆糊*1"}},{type="itemin",args={"23qxrwwp06",1}},{type="showbutton",args={1,0}},{type="showbutton",args={2,1}}},